DECLARE @to datetime2 = $__timeTo();
DECLARE @day datetime2 = CAST(CAST(CAST(@to AT TIME ZONE 'UTC' AT TIME ZONE 'GMT Standard Time' AS date) AS datetime2) AT TIME ZONE 'GMT Standard Time' AT TIME ZONE 'UTC' AS datetime2);
SELECT MIN(TemperatureMinC) AS [Min], MAX(TemperatureMaxC) AS [Max] FROM dbo.Outdoor
WHERE TimeUtc >= @day AND TimeUtc <= @to

DECLARE @to datetime2 = $__timeTo();
SELECT AVG(WindAvgMs) * 2.23694 AS [Wind], MAX(GustMaxMs) * 2.23694 AS [Gust] FROM dbo.Outdoor
WHERE TimeUtc <= @to AND TimeUtc > DATEADD(MINUTE, -10, @to)

DECLARE @to datetime2 = $__timeTo();
DECLARE @day datetime2 = CAST(CAST(CAST(@to AT TIME ZONE 'UTC' AT TIME ZONE 'GMT Standard Time' AS date) AS datetime2) AT TIME ZONE 'GMT Standard Time' AT TIME ZONE 'UTC' AS datetime2);
SELECT ISNULL(ROUND(SUM(CASE WHEN TimeUtc >= @day THEN RainMm END), 1), 0) AS [Today],
       ISNULL(ROUND(SUM(RainMm), 1), 0) AS [24 hours]
FROM dbo.Outdoor
WHERE TimeUtc <= @to AND TimeUtc > DATEADD(HOUR, -24, @to)

DECLARE @to datetime2 = $__timeTo();
DECLARE @p float, @t datetime2;
SELECT TOP 1 @p = PressureHpa, @t = TimeUtc FROM dbo.Pressure WHERE TimeUtc <= @to AND TimeUtc > DATEADD(HOUR, -3, @to) ORDER BY TimeUtc DESC;
SELECT @p AS [Pressure], @p - (SELECT TOP 1 PressureHpa FROM dbo.Pressure WHERE TimeUtc <= DATEADD(HOUR, -3, @t) AND TimeUtc > DATEADD(HOUR, -4, @t) ORDER BY TimeUtc DESC) AS [3 h change]
WHERE @p IS NOT NULL
